// Connection Check: one line per login, with the error and the fix when it fails.
const business = String($('Check Form').first().json['Business name'] || 'your business').trim();
const errText = (e) => String((e && (e.message || e.description)) || e || '').split('\n')[0].slice(0, 140);
const lines = [];
let ok = 0;

// Google Sheets: an error item means the credential failed; otherwise count the rows it could read.
const sheet = $('Google Sheets').all();
const sheetErr = sheet[0] && sheet[0].json && sheet[0].json.error;
if (sheetErr) lines.push(`✗ Google Sheets: ${errText(sheetErr)}. Fix: reconnect the Google credential.`);
else { ok++; lines.push(`✓ Google Sheets: connected, ${sheet.filter(i => Object.keys(i.json).length).length} rows in Leads.`); }

// Gmail: same idea, read-only.
const mail = $('Gmail').first().json;
if (mail.error) lines.push(`✗ Gmail: ${errText(mail.error)}. Fix: reconnect the Gmail credential.`);
else { ok++; lines.push('✓ Gmail: connected, inbox readable.'); }

// OpenAI: 200 means the key works. 401 = no key or wrong key. 429 = key works but no credit.
const ai = $('OpenAI').first().json;
if (ai.statusCode === 200) { ok++; lines.push('✓ OpenAI: connected.'); }
else {
  const msg = (ai.body && ai.body.error && ai.body.error.message) || errText(ai.error) || 'no answer';
  const fix = ai.statusCode === 429 ? 'add credit under Billing' : 'paste your API key into an OpenAI credential';
  lines.push(`✗ OpenAI: ${ai.statusCode || 'error'}, ${msg.split('. ')[0]}. Fix: ${fix}.`);
}

// Slack: auth.test answers ok true with a working bot token.
const sl = $('Slack').first().json;
if (sl.body && sl.body.ok) { ok++; lines.push(`✓ Slack: connected as ${sl.body.user}.`); }
else lines.push(`✗ Slack: ${(sl.body && sl.body.error) || errText(sl.error) || 'no answer'}. Fix: paste your bot token (xoxb-) into a Slack credential.`);

return [{ json: { business, ok, total: 4, title: `${ok} of 4 connected for ${business}`, report: lines.join('\n') } }];
